import {approvedInterfaceIcons as icons} from './approved-interface-entry.js';
import {rewardIcons,missionArt} from './missions-assets.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Math.floor(n).toLocaleString('pt-BR');
const key=id=>escape(encodeURIComponent(id));
const icon=id=>`<span class="mission-value-icon" aria-hidden="true">${rewardIcons[id]||''}</span>`;
function objective(card){const verb=card.verb;if(/^(Quebre|Derrote|Acerte|Ganhe|Complete|Use) /.test(verb)){const first=verb.indexOf(' ');return escape(verb.slice(0,first))+' <b>'+number(card.goal)+'</b> '+escape(verb.slice(first+1));}return escape(verb)+' <b>'+number(card.goal)+'</b>';}
function art(id,fallback=''){return missionArt[id]?`<img src="${escape(missionArt[id])}" alt="" draggable="false">`:fallback;}
function row(card,accepted){
 const ready=accepted&&card.status==='ready',expired=accepted&&card.status==='expired';
 const state=ready?'Pronta para receber':expired?'Prazo encerrado':accepted?'Aceita · '+escape(card.timeText)+' · Pausada no refúgio':escape(card.timeText)+' de exploração';
 const action=!accepted?`<button type="button" class="primary" data-mission="${key(card.id)}">Aceitar →</button>`:ready?`<button type="button" class="primary" data-claim-mission="${key(card.id)}">Receber</button>`:expired?`<button type="button" class="secondary" data-abandon-mission="${key(card.id)}">Limpar</button>`:'<strong class="r2-mission-running">Aceita</strong>';
 const family={miner:'crystals',quartz:'quartz',prism:'ruby',geode:'topaz',vital:'emerald',rocks:'rocks',brute:'rocks',hunter:'slime',slime:'slime',guardians:'golem',bats:'bat',beats:'music',combo:'music',points:'trophy',items:'pulse-potion',bombs:'bomb',cures:'pulse-potion',floors:'stairs-floors',depth4:'stairs-floors',depth8:'stairs-floors'}[card.template];
 const progress=Number.isFinite(card.progress)?card.progress:0,goal=card.goal;
 const width=goal>0?Math.max(0,Math.min(100,progress/goal*100)):0;
 return `<li class="r2-mission-card" data-mission-status="${accepted?escape(card.status):'available'}" data-mission-tier="${escape(card.tierName)}"><span class="r2-mission-icon" aria-hidden="true">${art(family,icons.mission(card.template))}</span><div class="r2-mission-copy"><span class="r2-mission-tier">Nv. ${number(card.rewardLevel)} · ${escape(card.tierName)}</span><h3>${objective(card)}</h3><p>${state}</p><div class="r2-mission-progress" role="progressbar" aria-label="${escape(card.name)}" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${progress}"><i style="width:${width}%"></i><strong>${number(progress)} / ${number(goal)}</strong></div></div><div class="r2-mission-reward"><strong>${icon('coin')}<span>+ ${number(card.reward.gems)}<small> moedas</small></span></strong><small title="Pequena chance ao entregar">${icon('rare-record')}Chance de disco raro</small></div><div class="r2-mission-action">${action}</div></li>`;
}
// The only trusted fragment is the existing buildingMarkup(s,'missions').
function buildingControl(html){return html.replace('</summary>','</summary><div class="building-popover">').replace('</details>','</div></details>');}
export function missionBoardMarkup(vm){
 const active=vm.active.filter(m=>m.status==='active');
 const offers=vm.used<vm.slots?vm.offers:[];
 return `<section class="r2-missions" aria-label="Missões do Refúgio"><div class="r2-missions-top" tabindex="-1"><div class="missions-summary-title"><span class="missions-summary-art" aria-hidden="true">${art('missions-scroll-summary')}</span><div><h2>Missões do Refúgio</h2><p>Escolha um objetivo antes de descer.</p></div></div><div class="missions-capacity"><div class="missions-capacity-bar"><i style="width:${Math.max(0,Math.min(100,vm.used/vm.slots*100))}%"></i><strong>${number(vm.used)} / ${number(vm.slots)} vagas ocupadas</strong></div><p>${vm.nextSlot?'Próxima vaga · Nv. '+number(vm.nextSlot):'Cinco vagas liberadas'} · Quadro Nv. ${number(vm.level)} / ${number(vm.cap)}</p></div><div class="r2-missions-balances"><span>${icon('coin')}${number(vm.bank)} moedas</span></div><div class="r2-missions-toolbar">${buildingControl(vm.buildingHtml)}</div></div><ul class="r2-mission-list" aria-label="Missões aceitas e disponíveis">${vm.active.map(c=>row(c,true)).join('')}${offers.map(c=>row(c,false)).join('')}</ul>${vm.used>=vm.slots?'<p class="r2-missions-full">Vagas cheias · conclua e receba para aceitar outra missão.</p>':''}${!vm.active.length&&!offers.length?'<p class="r2-missions-full">Nenhuma missão disponível.</p>':''}${active.length?`<details id="missionOptions" class="r2-missions-details"><summary>Trocar missão</summary>${active.map(m=>`<button type="button" class="secondary" data-abandon-mission="${key(m.id)}">Abandonar · ${escape(m.name)}</button>`).join('')}</details>`:''}<details id="missionRules" class="r2-missions-details"><summary>Chances e regras</summary><p>Raras: ${Math.round(vm.odds.rare*100)}% · Douradas: ${Math.round(vm.odds.gold*100)}%.</p><p>${vm.questLuck?'Olho de Ouro ativo.':'Olho de Ouro aumenta as chances na árvore.'}</p><p>Mais vagas nos níveis 30, 60, 90 e 120. Máximo de cinco.</p><p>Aceitar e entregar sorteia novas ofertas. Missões aceitas continuam guardadas.</p><p>O prazo só corre na caverna. Progresso continua após a morte. Receba no refúgio.</p></details></section>`;
}

export function missionReceiptMarkup(vm){return `<section class="mission-receipt r2-missions-receipt"><span class="receipt-check" aria-hidden="true">✓</span><h2>Recompensa recebida!</h2><div class="receipt-rewards"><div><strong>${icon('coin')} +${number(vm.reward.gems)}</strong><span>Moedas</span></div></div>${vm.record?`<div class="record-receipt">♫ Disco raro · ${escape(vm.record.name)}</div>`:''}<button type="button" class="primary" id="receiptDone">Fechou!</button><button type="button" class="secondary" id="moreMissions">Nova missão →</button></section>`;}
